function loadZhMap() {
  try {
    const c = JSON.parse(readFileSync(REGISTRY_CACHE, 'utf8'));
    if (c && c.map && typeof c.at === 'number') {
      if (Date.now() - c.at > REGISTRY_TTL) refreshZhMap();
      return c.map;
    }
  } catch {
    /* 还没有缓存 */
  }
  refreshZhMap();
